targets.expr:
1000 *
sum by (client_name) (
  rate(http_client_requests_seconds_sum{
    application="offering-service",
    client_name=~".*(user-service|analysis-service|UserServiceClient|AnalysisServiceClient).*"
  }[$__rate_interval])
)
/
clamp_min(
  sum by (client_name) (
    rate(http_client_requests_seconds_count{
      application="offering-service",
      client_name=~".*(user-service|analysis-service|UserServiceClient|AnalysisServiceClient).*"
    }[$__rate_interval])
  ),
  0.000001
)

100 *
sum by (method, uri) (
  rate(
    http_server_requests_seconds_count{
      application="offering-service",
      uri=~"/api/v1/.*",
      status=~"2.."
    }[$__rate_interval]
  )
)
/
sum by (method, uri) (
  rate(
    http_server_requests_seconds_count{
      application="offering-service",
      uri=~"/api/v1/.*"
    }[$__rate_interval]
  )
)

100 *
(
  sum by (method, uri) (
    rate(
      http_server_requests_seconds_count{
        application="offering-service",
        uri=~"/api/v1/.*",
        status=~"5.."
      }[$__rate_interval]
    )
  )
  or
  (
    sum by (method, uri) (
      rate(
        http_server_requests_seconds_count{
          application="offering-service",
          uri=~"/api/v1/.*"
        }[$__rate_interval]
      )
    ) * 0
  )
)
/
clamp_min(
  sum by (method, uri) (
    rate(
      http_server_requests_seconds_count{
        application="offering-service",
        uri=~"/api/v1/.*"
      }[$__rate_interval]
    )
  ),
  0.000001
)

sum(jvm_memory_used_bytes{
  application="offering-service",
  area="heap"
})
/
sum(jvm_memory_max_bytes{
  application="offering-service",
  area="heap"
})
* 100

sum by (method, uri) (
  rate(
    http_server_requests_seconds_count{
      application="offering-service",
      uri=~"/api/v1/.*"
    }[$__rate_interval]
  )
)

1000 *
sum(
  rate(
    http_server_requests_seconds_sum{
      application="offering-service",
      uri=~"/api/v1/.*"
    }[$__rate_interval]
  )
)
/
sum(
  rate(
    http_server_requests_seconds_count{
      application="offering-service",
      uri=~"/api/v1/.*"
    }[$__rate_interval]
  )
)

1000 *
histogram_quantile(
  0.95,
  sum by (le) (
    rate(
      http_server_requests_seconds_bucket{
        application="offering-service",
        uri=~"/api/v1/.*"
      }[$__rate_interval]
    )
  )
)

1000 *
sum by (result) (
  rate(
    outbox_publish_latency_seconds_sum{
      application="offering-service"
    }[$__rate_interval]
  )
)
/
clamp_min(
  sum by (result) (
    rate(
      outbox_publish_latency_seconds_count{
        application="offering-service"
      }[$__rate_interval]
    )
  ),
  0.000001
)

sum by (result) (
